// ===== Oncode driver I/O (inlined by backend/seed/tools/lib/codegen.js) =====
// Input: one value per line in canonical form (see backend/seed/FORMAT.md). Output: canonical form.
namespace oncode {

// Nullable int, for level-order tree arrays such as [1,null,2].
struct Opt {
    bool has = false;
    int v = 0;
};

struct Reader {
    std::string s;
    size_t p = 0;
    Reader() {
        std::ios::sync_with_stdio(false);
        s.assign(std::istreambuf_iterator<char>(std::cin), std::istreambuf_iterator<char>());
    }
    [[noreturn]] void fail(const char* what) {
        std::cerr << "driver input error: " << what << " at byte " << p << "\n";
        std::exit(3);
    }
    void ws() {
        while (p < s.size() && std::isspace(static_cast<unsigned char>(s[p]))) p++;
    }
    bool peek(char c) {
        ws();
        return p < s.size() && s[p] == c;
    }
    void expect(char c) {
        if (!peek(c)) fail("unexpected character");
        p++;
    }
    long long integer(long long lo, long long hi) {
        ws();
        bool neg = false;
        if (p < s.size() && s[p] == '-') { neg = true; p++; }
        size_t start = p;
        long long v = 0;
        while (p < s.size() && std::isdigit(static_cast<unsigned char>(s[p]))) {
            if (p - start >= 18) fail("integer too long");
            v = v * 10 + (s[p++] - '0');
        }
        if (p == start) fail("expected integer");
        if (neg) v = -v;
        if (v < lo || v > hi) fail("integer out of range");
        return v;
    }
    void read(int& x) { x = static_cast<int>(integer(INT_MIN, INT_MAX)); }
    void read(long long& x) { x = integer(-999999999999999999LL, 999999999999999999LL); }
    void read(bool& x) {
        ws();
        if (s.compare(p, 4, "true") == 0) { x = true; p += 4; }
        else if (s.compare(p, 5, "false") == 0) { x = false; p += 5; }
        else fail("expected true or false");
    }
    void read(std::string& x) {
        expect('"');
        x.clear();
        while (p < s.size() && s[p] != '"') {
            if (s[p] == '\\') {
                p++;
                if (p >= s.size()) break;
            }
            x += s[p++];
        }
        if (p >= s.size()) fail("unterminated string");
        p++;
    }
    void read(Opt& o) {
        ws();
        if (s.compare(p, 4, "null") == 0) { o.has = false; p += 4; }
        else { o.has = true; o.v = static_cast<int>(integer(INT_MIN, INT_MAX)); }
    }
    void read(char& x) {
        std::string t;
        read(t);
        if (t.size() != 1) fail("expected one-character string");
        x = t[0];
    }
    template <class T> void read(std::vector<T>& v) {
        v.clear();
        expect('[');
        if (peek(']')) { p++; return; }
        for (;;) {
            T e;
            read(e);
            v.push_back(std::move(e));
            if (peek(',')) { p++; continue; }
            expect(']');
            return;
        }
    }
    void end() {
        ws();
        if (p != s.size()) fail("unexpected trailing input");
    }
};

struct Writer {
    std::string out;
    void write(int x) { out += std::to_string(x); }
    void write(long long x) { out += std::to_string(x); }
    void write(bool x) { out += x ? "true" : "false"; }
    void write(const std::string& x) {
        out += '"';
        for (char c : x) {
            if (c == '"' || c == '\\') out += '\\';
            out += c;
        }
        out += '"';
    }
    void write(char c) { write(std::string(1, c)); }
    void write(const Opt& o) {
        if (o.has) write(o.v);
        else out += "null";
    }
    template <class T> void write(const std::vector<T>& v) {
        out += '[';
        for (size_t i = 0; i < v.size(); i++) {
            if (i) out += ',';
            write(v[i]);
        }
        out += ']';
    }
    void line() { out += '\n'; }
    void flush() {
        std::fwrite(out.data(), 1, out.size(), stdout);
        std::fflush(stdout);
    }
};

}  // namespace oncode

namespace oncode {
TreeNode* buildTree(const std::vector<Opt>& v) {
    if (v.empty() || !v[0].has) return nullptr;
    TreeNode* root = new TreeNode(v[0].v);
    std::queue<TreeNode*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < v.size()) {
        TreeNode* n = q.front();
        q.pop();
        if (i < v.size() && v[i].has) { n->left = new TreeNode(v[i].v); q.push(n->left); }
        i++;
        if (i < v.size() && v[i].has) { n->right = new TreeNode(v[i].v); q.push(n->right); }
        i++;
    }
    return root;
}
std::vector<Opt> treeOut(TreeNode* root) {
    std::vector<Opt> r;
    std::queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        TreeNode* n = q.front();
        q.pop();
        Opt o;
        if (n) {
            o.has = true;
            o.v = n->val;
            q.push(n->left);
            q.push(n->right);
        }
        r.push_back(o);
        if (r.size() > 400000) { std::cerr << "driver: returned structure is too large or has a cycle\n"; std::exit(4); }
    }
    while (!r.empty() && !r.back().has) r.pop_back();
    return r;
}
TreeNode* findNode(TreeNode* root, int val) {
    std::vector<TreeNode*> st;
    if (root) st.push_back(root);
    while (!st.empty()) {
        TreeNode* n = st.back();
        st.pop_back();
        if (n->val == val) return n;
        if (n->left) st.push_back(n->left);
        if (n->right) st.push_back(n->right);
    }
    return nullptr;
}
Opt nodeVal(TreeNode* n) {
    Opt o;
    if (n) { o.has = true; o.v = n->val; }
    return o;
}
}  // namespace oncode

int main() {
    oncode::Reader oc_in;
    vector<int> preorder;
    oc_in.read(preorder);
    vector<int> inorder;
    oc_in.read(inorder);
    oc_in.end();
    Solution oc_sol;
    TreeNode* oc_res = oc_sol.buildTree(preorder, inorder);
    oncode::Writer oc_out;
    oc_out.write(oncode::treeOut(oc_res));
    oc_out.line();
    oc_out.flush();
    return 0;
}

