class Solution {
    unordered_map<int, int> pos;  // value -> index in inorder
    int next = 0;                 // next preorder index to use
    TreeNode* build(const vector<int>& pre, int lo, int hi) {  // inorder range [lo, hi]
        if (lo > hi) return nullptr;
        TreeNode* root = new TreeNode(pre[next++]);
        int mid = pos[root->val];
        root->left = build(pre, lo, mid - 1);
        root->right = build(pre, mid + 1, hi);
        return root;
    }
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        for (int i = 0; i < (int)inorder.size(); i++) pos[inorder[i]] = i;
        next = 0;
        return build(preorder, 0, (int)inorder.size() - 1);
    }
};

class Solution {
    // Iterative stack-based construction (the C++ reference is recursive with an index map).
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        TreeNode root = new TreeNode(preorder[0]);
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        int in = 0;
        for (int i = 1; i < preorder.length; i++) {
            TreeNode node = new TreeNode(preorder[i]);
            TreeNode parent = stack.peek();
            if (parent.val != inorder[in]) {
                parent.left = node; // still going down the left side
            } else {
                // climb while the stack top is the next in-order value; attach as right child
                while (!stack.isEmpty() && stack.peek().val == inorder[in]) {
                    parent = stack.pop();
                    in++;
                }
                parent.right = node;
            }
            stack.push(node);
        }
        return root;
    }
}
